/*
 * WHAT THE SELECT OFFERS (TASK-L165 §2). PORTED: ProgrammeScope.tsx.
 *
 * THIS FUNCTION MUST NEVER READ THE SELECT'S OWN VALUE. A Dropdown handed a new
 * `items` array resets itself to its `value` parameter (L164, measured), so
 * options recomputed on every choice would snap the select straight back to
 * the current programme in the same tick, and the control would look dead.
 *
 * "current" means the CURRENT programme — what is on their page now. The
 * product uses "" for it; a NodeGX Dropdown adds its own hidden placeholder
 * option at value "", so two options shared one value and choosing the
 * current programme again after a finished one was ambiguous (measured on the
 * first render). A word nobody's programme id can be is unambiguous, and the
 * default is still a static parameter that needs no wire.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const fill = (t, v) => String(t || '').replace(/\{(\w+)\}/g, (m, k) => (k in v ? String(v[k]) : m));
if (Inputs.copy === undefined || Inputs.copy === null) return;
const W = ((plain(Inputs.copy) || {}).people || {}).learner;
if (!W) throw new Error('People/Programme scope: no people.learner copy');
const programmes = plain(Inputs.programmes) || [];

/* PORTED, NEVER RE-DERIVED: currentProgramme -> src/lib/programme/current.ts.
   The active, unarchived one whose agreed end has not passed, nearest end
   first; among EXPIRED ends the nearest is the LATEST (the product's first
   implementation got that direction wrong); then the most recently created. */
const currentProgramme = (list, now) => {
  const live = list.filter((p) => p.status === 'active' && p.archivedAt === null);
  if (live.length === 0) return null;
  const today = now.toISOString().slice(0, 10);
  const expired = (p) => p.endsOn !== null && p.endsOn !== undefined && p.endsOn < today;
  return live.slice().sort((a, b) => {
    if (expired(a) !== expired(b)) return expired(a) ? 1 : -1;
    if (a.endsOn !== b.endsOn) {
      if (a.endsOn === null) return 1;
      if (b.endsOn === null) return -1;
      const nearestFirst = a.endsOn < b.endsOn ? -1 : 1;
      return expired(a) ? -nearestFirst : nearestFirst;
    }
    return a.createdAt < b.createdAt ? 1 : a.createdAt > b.createdAt ? -1 : 0;
  })[0];
};

const FORMAT = new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' });
const day = (d) => (d ? FORMAT.format(new Date(d + 'T12:00:00.000Z')) : '');

/* STRUCTURALLY ABSENT BELOW TWO (sprint 35 §5.2): a select with one option is a
   control that does nothing, and the common case must not get worse. */
Outputs.hasSelect = programmes.length >= 2;
Outputs.label = W.scope.label;
const current = currentProgramme(programmes, new Date());
Outputs.options = [{ Label: current ? fill(W.scope.current, { title: current.title }) : W.scope.everything, Value: 'current' }].concat(
  programmes
    .filter((p) => !current || p.id !== current.id)
    .map((p) => ({
      Label: fill(W.scope.option, { title: p.title, from: day(p.startsOn) }) +
        (p.endsOn ? fill(W.scope.optionTo, { to: day(p.endsOn) }) : '') +
        (p.archivedAt !== null ? W.scope.finished : ''),
      Value: p.id
    }))
);

/*
 * WHAT IS BEING READ (TASK-L165 §2). BOTH surfaces read this, which is why the
 * control sits above the nav rather than inside either (L137: the selector sat
 * on one tab only, so on the tab named after the programme there was no way to
 * say which programme you were reading).
 *
 *  - "current" is what is on their page NOW — the live list, untouched, which is the
 *    list the learner's own page is built from. A coach reading the current
 *    programme reads exactly what their client reads (L116, criterion 1).
 *  - any other id is a FINISHED programme's history: a STRICT filter, because
 *    that is what the product's history read returns (scopeToProgramme,
 *    model.ts). In the product it is a separate, gated fetch; here it is the
 *    fixture's `history`.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const fill = (t, v) => String(t || '').replace(/\{(\w+)\}/g, (m, k) => (k in v ? String(v[k]) : m));
if (Inputs.copy === undefined || Inputs.copy === null) return;
const W = ((plain(Inputs.copy) || {}).people || {}).learner;
if (!W) throw new Error('People/Programme scope: no people.learner copy');
const live = plain(Inputs.entries);
if (!live) return;
const programmes = plain(Inputs.programmes) || [];
const history = plain(Inputs.history) || [];
const dimensions = plain(Inputs.dimensions) || [];
const chosen = String(Inputs.chosen || '');
const viewing = chosen && chosen !== 'current' ? programmes.find((p) => p.id === chosen) || null : null;

const FORMAT = new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' });
const day = (d) => (d ? FORMAT.format(new Date(d + 'T12:00:00.000Z')) : '');

if (!viewing) {
  Outputs.entries = live;
  /* The live programme's own objectives. A second agreement's targets drawn on
     this programme's axis is the average L127 §2 forbids in a different
     costume, so the dimensions are scoped with the entries. */
  const ids = new Set(live.map((e) => e.programmeId).filter(Boolean));
  Outputs.dimensions = dimensions.filter((d) => ids.has(d.programmeId));
  Outputs.endsOn = Inputs.endsOn || '';
  Outputs.viewing = false;
  Outputs.reading = '';
} else {
  Outputs.entries = live.concat(history).filter((e) => e.programmeId === viewing.id);
  Outputs.dimensions = dimensions.filter((d) => d.programmeId === viewing.id);
  Outputs.endsOn = viewing.endsOn || '';
  Outputs.viewing = true;
  /* A COUNT of nothing, and never a mark: whether the person "finished" is not a
     question this product asks, and a history page is exactly where that
     framing would come back looking harmless (L124 §4). */
  Outputs.reading = fill(W.scope.reading, {
    title: viewing.title,
    from: day(viewing.startsOn),
    to: viewing.endsOn ? fill(W.scope.optionTo, { to: day(viewing.endsOn) }) : ''
  });
}
